                            h("div", { className: "dsh-tavern-rx-row-preview" },
                                h("code", null, current.findRegex || "（空）"), " → ", h("code", null, current.replaceString || "（删除匹配）")),
                            h("div", { className: "dsh-tavern-rx-tags" }, tagsFor(source, entry, draft))
